def _handoff_ooma_section():
    data = _fetch_ooma_dashboard()
    if data is None:
        return _bridge_unreachable_html("Ooma AirDial", SYSTEMS["ooma"]["base_url"])
    rows = _ooma_issue_rows_html(data["issues"])
